package com.billingcopilot.service;
import com.billingcopilot.model.BillingModels.*; import com.billingcopilot.repository.ContractBillingRuleRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class ContractAuditService { private final com.billingcopilot.repository.ContractDocumentRepository documents; private final ContractBillingRuleRepository rules; private final ReconciliationService reconciliation; public ContractAuditService(com.billingcopilot.repository.ContractDocumentRepository documents,ContractBillingRuleRepository r,ReconciliationService s){this.documents=documents;rules=r;reconciliation=s;} public AuditResult audit(long contractId,List<WorkItem> work,List<InvoiceItem> invoice){var doc=documents.findById(contractId).orElseThrow(); com.billingcopilot.security.PilotScope.require(doc.getTenantId());var approved=rules.findByContractDocumentIdAndReviewStatusOrderById(contractId,"APPROVED").stream().map(r->new BillingRule(r.getService(),r.getRate(),r.getUnit())).toList(); if(approved.isEmpty()) throw new IllegalStateException("Approve at least one contract rule before running an audit"); return reconciliation.audit(new AuditRequest(approved,work,invoice));}}
